fn pair<T>(first: T, second: T) -> (T, T) {
    (first, second)
}

let numbers = pair(1, 2);
let words = pair("rust", "book");

trait Summary {
    fn summary(&self) -> String;
}

struct Article { title: String }
impl Summary for Article {
    fn summary(&self) -> String { self.title.clone() }
}

fn largest<T: PartialOrd + Copy>(values: &[T]) -> Option<T> {
    values.iter().copied().reduce(|left, right| if left > right { left } else { right })
}
